{
  "findings": [
    {
      "check_id": "CKV_GCP_83",
      "title": "Pub/Sub topic is not encrypted with a customer-managed key",
      "resource": "google_pubsub_topic.notification_queue",
      "severity": "MEDIUM",
      "explanation": "The production notification topic does not specify a KMS key, so it relies on Google-managed encryption rather than the customer-supplied encryption required by the applicable policy."
    }
  ],
  "patched_code": "variable "pubsub_kms_key_name" {
  description = "Fully qualified Cloud KMS CryptoKey name used to encrypt the Pub/Sub topic."
  type        = string
}

resource "google_pubsub_topic" "notification_queue" {
  name         = "insurance-claims-processing-platform-pubsub-notifications"
  kms_key_name = var.pubsub_kms_key_name

  labels = {
    environment = "production"
    component   = "notifications"
  }
}
",
  "fix_summary": "Added a required KMS key input and configured the Pub/Sub topic to use that key for encryption."
}
